const items = $input.all();
const webhookData = $("High-Risk Webhook").first().json.body || {};
const dbRows = $("Fetch Patient & Consultant Info").all().map(i => i.json);

const patientName = (dbRows[0] && dbRows[0].patient_name) || webhookData.full_name || ('Patient #' + webhookData.user_id);
const patientEmail = (dbRows[0] && dbRows[0].patient_email) || webhookData.email || 'N/A';
const consultantEmail = (dbRows[0] && dbRows[0].consultant_email) || 'admin@healthly.com';
const riskLevel = webhookData.risk_level || 'High';
const score = webhookData.score !== undefined ? webhookData.score : (webhookData.phq9_score !== undefined ? webhookData.phq9_score : 'N/A');
const dominantEmotion = webhookData.dominant_emotion || 'Severe Distress';
const concernAreas = Array.isArray(webhookData.concern_areas) ? webhookData.concern_areas.join(', ') : (webhookData.concern_areas || 'Depression, High Risk');
const timestamp = webhookData.timestamp || new Date().toISOString();
const dashboardLink = 'http://localhost:5173/consultant/patients/' + webhookData.user_id;

const alertSubject = '🚨 [URGENT] High-Risk Mental Health Escalation: ' + patientName;
const alertBody = '=====================================================\n🚨 HIGH-RISK MENTAL HEALTH ESCALATION ALERT\n=====================================================\n\nPatient Details:\n----------------\n• ID: ' + webhookData.user_id + '\n• Name: ' + patientName + '\n• Email: ' + patientEmail + '\n\nClinical Risk Summary:\n----------------------\n• Risk Level: ' + riskLevel + '\n• PHQ-9 Score: ' + score + ' / 27\n• Dominant Emotion: ' + dominantEmotion + '\n• Primary Concern Areas: ' + concernAreas + '\n• Timestamp: ' + timestamp + '\n\nAction Required:\n----------------\nPlease review the patient details immediately in the Consultant Dashboard:\n' + dashboardLink + '\n\n=====================================================\nSystem: Healthly Automated Escalation Service (n8n Workflow #1)\n';

return [{
  json: {
    user_id: webhookData.user_id,
    patient_name: patientName,
    patient_email: patientEmail,
    consultant_email: consultantEmail,
    risk_level: riskLevel,
    score: score,
    dominant_emotion: dominantEmotion,
    concern_areas: concernAreas,
    timestamp: timestamp,
    dashboard_link: dashboardLink,
    alert_subject: alertSubject,
    alert_body: alertBody,
    status: 'ESCALATED_NOTIFICATION_SENT'
  }
}];

const item = $input.first().json;
console.log('=========================================');
console.log('EMAIL NOTIFICATION DELIVERED TO CONSULTANT:');
console.log('TO: ' + item.consultant_email);
console.log('SUBJECT: ' + item.alert_subject);
console.log(item.alert_body);
console.log('=========================================');

return [{
  json: {
    ...item,
    email_delivered: true,
    delivered_at: new Date().toISOString()
  }
}];

const item = $input.first().json;
return [{
  json: {
    workflow: 'Workflow 1: High-Risk Escalation Alert',
    status: 'SUCCESS',
    execution_confirmed: true,
    user_id: item.user_id,
    logged_at: new Date().toISOString(),
    details: item
  }
}];
